sections.content:
ElevatedButton(
onPressed: () {
print('Кнопка нажата');
},
child: const Text('Основное действие'),
)

ElevatedButton(
onPressed: () {},
style: ElevatedButton.styleFrom(
// Цвета
foregroundColor: Colors.white,
backgroundColor: Colors.blue,
disabledForegroundColor: Colors.grey,
disabledBackgroundColor: Colors.grey[300],
// Размеры
padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
minimumSize: const Size(88, 36),
// Скругление
shape: RoundedRectangleBorder(
borderRadius: BorderRadius.circular(8),
),
// Тень
elevation: 4,
// Переходы
animationDuration: const Duration(milliseconds: 200),
),
child: const Text('Стильная кнопка'),
)

TextButton(
onPressed: () {
print('Текстовая кнопка');
},
child: const Text('Подробнее'),
)

OutlinedButton(
onPressed: () {
print('Кнопка с рамкой');
},
child: const Text('Отменить'),
)

// Кастомный цвет в зависимости от состояния
ButtonStyle(
backgroundColor: MaterialStateProperty.resolveWith((states) {
if (states.contains(MaterialState.pressed)) {
return Colors.blue.shade700;
}
if (states.contains(MaterialState.disabled)) {
return Colors.grey[300];
}
return Colors.blue;
}),
)

IconButton(
onPressed: () {
print('Иконка нажата');
},
icon: const Icon(Icons.favorite),
color: Colors.red,
hoverColor: Colors.redAccent,
splashRadius: 24,
)

// Активная кнопка
ElevatedButton(
onPressed: () {},
child: const Text('Активна'),
)

// Отключённая кнопка
ElevatedButton(
onPressed: null, // null = отключено
child: const Text('Отключена'),
)

// Кнопка с индикатором загрузки
ElevatedButton(
onPressed: isLoading ? null : () => submitForm(),
child: isLoading
? const SizedBox(
height: 20,
width: 20,
child: CircularProgressIndicator(strokeWidth: 2),
)
: const Text('Отправить'),
)
